// Below is the default definition for marketing channels pre-created for you. You can use this as-is or modify it to suit your business needs.

// NOTE: This formula is made up of if-elses, which means definitions above take priority over definitions below. So please note the order if you are modifying the definition

// Define variables for types of domains.
LET(
  search, ["google", "bing", "yahoo"],
LET(
  social, ["linkedin", "facebook", "twitter", "instagram"],
LET(
  shopping, ["amazon", "alibaba", "stripe", "ebay", "etsy", "shopify", "walmart"],

// Defining "Paid Search"
IFS(
  ( _A IN search OR  _B IN search)
  AND  _C IN ["cpc","ppc","paidsearch"],
  "Paid search",

  // Defining "Organic Search"
  ( _A IN search OR  _B IN search),
  "Organic search",

  // Defining "Social"
   _A IN social OR  _B IN social,
  "Social",

  // Defining "Shopping"
   _A IN shopping OR  _B IN shopping,
  "Shopping",

  // Defining "Email"
   _C = "email", "Email",

  // Defining "Display"
   _C IN ["display","cpm","banner"], "Display",

  // Defining "Other Advertising"
  DEFINED( _A ) OR DEFINED( _C ),"Other Advertising",

  // Excluding your own website's domain so it doesn't get counted as "Referral".
   _B  in  _D , UNDEFINED,

  // Defining "Referral".
  NOT  _B ="" AND DEFINED( _B ),"Referral",

// Defining "Direct". If there is no tracked UTM Source, UTM Medium or Referring Domain, channel is deemed "Direct"
  TRUE, "Direct"
))))

